  sc_t:'The scales', sc_d:'Put the tasks on the pans: what you can give to AI and what stays with you.', sc_ai:'AI', sc_you:'You', sc_done:'The scales are balanced. Work can be shared, but a person decides.', sc_again:'Start over', sc_bad:'Wrong pan.',
  h_p1:'The term "artificial intelligence" is much older than it seems. Six points that show how long the road to today\'s chatbots was.',
  f_p:'AI in this course is a man-made program that learned from examples and continues the most likely answer for your task. Not alive, not all-knowing and not an oracle, but a strong continuer that you steer and check. It speeds up the draft, and you are the editor.',
  f1t:'The term is almost 70', f1:'It was coined in 1955, before the Moon landing and home internet.',
  f2t:'Intelligence is not consciousness', f2:'It is about working with meaning, not about feelings and wishes.',
  f3t:'AI is an umbrella', f3:'A chatbot, an image generator and a voice assistant live under one word. What they share: they learned from examples.',
  q_t:'Three questions', q_ok:'Right.', q_bad:'Not quite.', q_pass:'Topic done, the sticker is yours.', q_fail:'Almost. Read the explanations and try again.', q_again:'Again',
  f_next:'Next topic: Not magic and not a calculator', f_back:'Back to layer 01',
  st:'Word taken apart', st_got:'Sticker: {n}',
  dr_parts:'Sections', dr_lang:'Language', dr_layer:'Back to layer 01', dr_course:'Back to courses', dr_core:'A.C.EON Core', dr_next:'Next topic',
  say0:'Let\'s take one word apart. I promise it won\'t be boring.', say1:'Walk around the apartment. Where am I hiding?', say2:'Tap the suggestions. Let\'s see what comes out.',
  say3:'Teach me to tell cats apart. I trust you. Completely.', say4:'Sort the tasks. No need to give me everything.', say5:'A bit of history. A short one, honestly.', say6:'Final. Three questions and the sticker is yours.',
  ok:['Exactly.','Just what I think.','Yes!'], bad:['Hmm, no.','Close. But no.','I would argue.'],
  room:{smartphone:['Smartphone with a keyboard','Word suggestions may run on AI, but the keyboard itself works without it.'],
    smart_speaker:['Smart speaker','The voice assistant recognizes speech and picks an answer.'],
    laptop:['Laptop with email','Email filters spam and suggests replies, but not everything in it needs AI.'],
    tv:['TV with movies','The movie picks adapt to your taste, the screen just shows them.'],
    robot_vacuum:['Robot vacuum','Some models map the rooms and choose a route, simple ones follow fixed rules.'],
    camera:['Camera by the gallery','The camera may recognize scenes and faces, but the shutter needs no AI.'],
    calculator:['Calculator','Counts by exact rules and does not learn from examples.'],
    light_switch:['Light switch','It just closes and opens a circuit.'],
    wall_clock:['Mechanical clock','A mechanism moves the hands, it has nothing to learn.'],
    toaster:['Toaster','Heats bread by a setting and does not recognize it.'],
    fridge:['Fridge with magnets','An ordinary fridge keeps the temperature, no AI.'],
    desk_lamp:['Desk lamp','Shines when switched on. Makes no decisions.']},
  cards:[['Sleeping cat','Even asleep, it is a cat. Confirmed by purring.'],['Jumping cat','A jump does not cancel the cat. Gravity is surprised though.'],['Black cat','Different color, same tail. It is a cat.'],['Ginger cat','Being ginger does not turn a cat into toast.'],
    ['Fluffy kitten','Small and fluffy, but already a cat.'],['Dog','It barked. Let\'s remove the cat label.'],['Fox','Similar ears, but it is a fox. I had to look twice too.'],['Toaster','If it meows, I will check the socket first.'],
    ['Fluffy slipper','Fluffy and homey, but it is a slipper.'],['Cat cloud','Cat-shaped, made of cloud.'],['Plush cat','A toy cat does not eat, sleep or knock over mugs.'],['Cat-shaped bread','The nose is painted on, inside it is crumb. It is bread.']],
  scale:[['Draft an email','ai','AI drafts fast.'],['Decide whether to send the email','you','The last word is yours.'],['Come up with 20 name ideas','ai','Going through options is a model strength.'],['Check a fact in a reliable source','you','Checking stays with a person.'],
    ['Explain a topic simply','ai','Explaining simply is something models do well.'],['Choose which goal matters more','you','People set goals.'],['Shorten a long text','ai','Shortening a text is a typical model task.'],['Be responsible for the result','you','Responsibility cannot be handed off.']],
  hist:[['1950','The question before the machines','Alan Turing writes the paper "Computing Machinery and Intelligence" and asks whether machines can think. He proposes the imitation game, later called the Turing test.'],
    ['1956','The word appears','John McCarthy and colleagues name the new field "artificial intelligence" in a proposal for a summer workshop at Dartmouth (written in 1955). The 1956 workshop is seen as the birth of AI as a science.'],
    ['1997','Chess','IBM\'s Deep Blue wins a match against world champion Garry Kasparov. This is not learning from examples yet, but a huge search through moves.'],
    ['2012','Pictures','The AlexNet neural network wins the ImageNet image recognition contest by a wide margin. The deep learning wave starts here.'],
    ['2016','Go','DeepMind\'s AlphaGo beats Lee Sedol, one of the strongest Go players. Go has far too many options to win by plain search.'],
    ['2022','Chatbots','ChatGPT comes out and the word "AI" reaches every home. By then the term is already more than 65 years old.']],
  quiz:[['What best describes how a model builds an answer?',['it takes a ready answer from a database','it continues the most likely continuation','it reads minds','it calls a friend'],1,'The model builds the answer again every time, from patterns and from your request.'],
    ['You trained a model on bad examples. What happens?',['it fixes everything itself','it learns the mistakes along with the right things','it refuses to learn','nothing changes'],1,'A model learns from what it was shown. The quality of the examples decides.'],
    ['Who is responsible for the decision if AI wrote the draft?',['the AI','whoever made the model','you','nobody'],2,'AI speeds up the draft, but the decision and the checking stay with you.']],
  ac:[{s:'Today my',st:[['quiet','busy','lunar'],['robot','neighbor','teapot'],['draws','writes','launches'],['a useful','a new','a dancing'],['plan','list','sandwich'],['for','after','without'],['school','work','gravity']]},
    {s:'In the evening our',st:[['little','sleepy','cosmic'],['cat','neighbor','carrot'],['found','noticed','woke up'],['an old','a new','a sleepy'],['toy','book','rocket'],['near','under','inside'],['the sofa','the table','the fridge']]},
    {s:'Tomorrow a',st:[['friendly','familiar','suspicious'],['neighbor','friend','banana'],['will bring','will show','will demand'],['fresh','new','royal'],['bread','drawings','thrones'],['for','after','instead of'],['breakfast','the meeting','the planet']]}]
